            var new_expr = p.newExpr(E.New{ .target = undefined, .args = undefined, .close_parens_loc = undefined }, loc);
            _ = &new_expr;
            _ = try p.parseExprWithFlags(.member, flags, (&new_expr.data.e_new.target));
