                        _ = &prop;
                        if (comptime Environment.allow_assert) {
                            _ = assert(((prop.key != null) or ((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value) != null)));
                        }
                        _ = ((properties.append(prop)) catch unreachable);
