                if ((p.lexer.token != .t_comma)) {
                    break;
                }
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
                _ = try p.lexer.next();
                if (p.lexer.has_newline_before) {
                    is_single_line = false;
                }
            }
            if (p.lexer.has_newline_before) {
                is_single_line = false;
            }
            const close_brace_loc = p.lexer.loc();
            _ = try p.lexer.expect(.t_close_brace);
            p.allow_in = old_allow_in;
            if (p.willNeedBindingPattern()) {
            } else {
