pub fn t_less_than(p: *P, level: Level, errors: ?*DeferredErrors, flags: Expr.EFlags) anyerror!Expr {
            const loc = p.lexer.loc();
            if (comptime (is_typescript_enabled and is_jsx_enabled)) {
